            "林雪晴": "https://img.remit.ee/api/file/BQACAgUAAyEGAASHRsPbAAIrAWhiBg3fWVnTgQ65kr0hTYE0Y-OYAAKnGAACqUgRV90ahH1FbTqiNgQ.png",
            "林梓依": "https://img.remit.ee/api/file/BQACAgUAAyEGAASHRsPbAAIrAAFoYgYMggV1QWXOm-eS6boI8xNV2gACphgAAqlIEVfidqTWbuaVBjYE.png",
            "林依依": "https://img.remit.ee/api/file/BQACAgUAAyEGAASHRsPbAAIrAmhiBg0rD2zd5cQ7afSiAqvM15VUAAKoGAACqUgRV3J25-6hTVh5NgQ.png"
        };
        function parseData(text) {
            const lines = text.trim().split('\\n');
            const data = { characters: [] };
            let currentCharacter = null;
            lines.forEach(line => {
                const parts = line.split(':');
                if (parts.length < 2) return;
                const key = parts[0].trim();
                const value = parts.slice(1).join(':').trim();
                switch(key) {
                    case '时间': data.time = value; break;
                    case '日期': data.date = value; break;
                    case '地点': data.location = value; break;
                    case '姓名':
                        if (currentCharacter) data.characters.push(currentCharacter);
                        currentCharacter = { '姓名': value };
                        break;
                    default:
                        if (currentCharacter) currentCharacter[key] = value;
                        break;
                }
            });
            if (currentCharacter) data.characters.push(currentCharacter);
            return data;
        }
        function renderUI(data) {
            ui.date.textContent = `日期: ${data.date || '未知'}`;
            ui.location.textContent = `地点: ${data.location || '未知'}`;
            ui.time.textContent = `时间: ${data.time || '未知'}`;
            ui.tabsContainer.innerHTML = '';
            ui.detailsWrapper.innerHTML = '';
            if (data.characters.length === 0) {
                 ui.placeholder.style.display = 'block';
                 ui.detailsWrapper.style.display = 'none';
                 return;
            }
            ui.placeholder.style.display = 'none';
            ui.detailsWrapper.style.display = 'block';
            data.characters.forEach((char, index) => {
                const tab = document.createElement('div');
                tab.className = 'hypno-char-tab';
                tab.textContent = char.姓名;
                tab.dataset.charIndex = index;
                ui.tabsContainer.appendChild(tab);
                const detailView = createDetailView(char, index);
                ui.detailsWrapper.appendChild(detailView);
                tab.addEventListener('click', () => {
                    document.querySelectorAll('.hypno-char-tab').forEach(t => t.classList.remove('active'));
                    tab.classList.add('active');
                    document.querySelectorAll('.character-detail-view').forEach(v => v.classList.remove('active'));
                    detailView.classList.add('active');
                });
            });
            if (ui.tabsContainer.firstChild) {
                ui.tabsContainer.firstChild.click();
            }
        }
        function createDetailView(char) {
            const view = document.createElement('div');
            view.className = 'character-detail-view';
            const avatarUrl = avatarMap[char.姓名] || 'https://i.imgur.com/placeholder.png';
            const statusClass = getStatusClass(char.催眠状态);
            view.innerHTML = `
                <style> @keyframes fadeIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } } </style>
                <div class="hypno-top-section">
                    <div class="hypno-avatar-section">
                        <div class="hypno-avatar-frame"><img src="${avatarUrl}" alt="${char.姓名}" class="hypno-avatar"></div>
                        <div class="hypno-char-name">${char.姓名}</div>
                        <div class="hypno-char-title">${char.身份 || ''}</div>
                    </div>
                    <div class="hypno-stat-bars">
                        <div class="hypno-stat-bar-container">
                            <div class="hypno-stat-bar-label"><span>好感度</span><span>${char.好感度 || 0}/100</span></div>
                            <div class="hypno-progress-bar-bg"><div class="hypno-progress-bar bar-good" style="width: ${char.好感度 || 0}%;"></div></div>
                        </div>
                        <div class="hypno-stat-bar-container">
                            <div class="hypno-stat-bar-label"><span>屈从度</span><span>${char.屈从度 || 0}/100</span></div>
                            <div class="hypno-progress-bar-bg"><div class="hypno-progress-bar bar-sub" style="width: ${char.屈从度 || 0}%;"></div></div>
                        </div>
                        <div class="hypno-stat-bar-container">
                            <div class="hypno-stat-bar-label"><span>淫欲度</span><span>${char.淫欲度 || 0}/100</span></div>
                            <div class="hypno-progress-bar-bg"><div class="hypno-progress-bar bar-lust" style="width: ${char.淫欲度 || 0}%;"></div></div>
                        </div>
                    </div>
                </div>
                <div class="hypno-info-grid">
                    <div class="hypno-info-item border-clothing">
                        <span class="hypno-info-label">服装</span>
                        <span class="hypno-info-value">${char.服装 || '未知'}</span>
                    </div>
                    <div class="hypno-info-item border-hypno-status">
                        <span class="hypno-info-label">催眠状态</span>
                        <span class="hypno-info-value status-${statusClass}">${char.催眠状态 || '未知'}</span>
                    </div>
                    <div class="hypno-info-item border-status">
                        <span class="hypno-info-label">状态</span>
                        <span class="hypno-info-value">${char.状态 || '未知'}</span>
                    </div>
                    <div class="hypno-info-item border-body">
                        <span class="hypno-info-label">乳房</span>
                        <span class="hypno-info-value">${char.乳房 || '未知'}</span>
                    </div>
                     <div class="hypno-info-item border-body">
                        <span class="hypno-info-label">小穴</span>
                        <span class="hypno-info-value">${char.小穴 || '未知'}</span>
                    </div>
                     <div class="hypno-info-item border-body">
                        <span class="hypno-info-label">后庭</span>
                        <span class="hypno-info-value">${char.后庭 || '未知'}</span>
                    </div>
                    <div class="hypno-info-item border-thought">
                        <span class="hypno-info-label">内心想法</span>
                        <span class="hypno-info-value">${char.内心想法 || '...'}</span>
                    </div>
                </div>`;
            return view;
        }
        function getStatusClass(status) {
            if (!status) return 'unhypnotized';
            status = status.toLowerCase();
            if (status.includes('未被催眠')) return 'unhypnotized';
            if (status.includes('浅层')) return 'light';
            if (status.includes('深层')) return 'deep';
            if (status.includes('植入')) return 'implanted';
            if (status.includes('覆盖')) return 'overwritten';
            return 'unhypnotized';
        }
        const rawData = dataContainer.textContent.trim().replace(/\[催眠启\]|\[催眠关\]|\[人物\]/g, '').replace(/\n/g, '\\n');
        if (rawData) {
            const parsedData = parseData(rawData);
            renderUI(parsedData);
        } else {
            console.error("No data found in container.");
            ui.placeholder.style.display = 'block';
            ui.detailsWrapper.style.display = 'none';
        }
    });
    </script>
</body>
</html>
